//! Intermediate representation for the vcad CAD ecosystem.
//!
//! This crate defines the DAG-based IR that represents parametric CAD models.
//! It is shared between the Rust and TypeScript sides of the vcad ecosystem.
//!
//! The IR is purely declarative — no mesh data, just a graph of operations.
//! Evaluation (meshing) is handled separately by the engine.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

pub mod ecad;
pub mod file_io;
pub mod to_loon;
pub mod vcode;

pub use vcad_tool_derive::ToolSchema;

/// A tool schema entry generated by the ToolSchema derive macro.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolSchemaEntry {
    /// Variant name in snake_case (e.g. "cube", "extrude").
    pub name: String,
    /// Description from doc comments.
    pub description: String,
    /// Category (e.g. "primitive", "sketch_op", "modifier").
    pub category: String,
    /// Optional AI hint for the system prompt.
    pub ai_hint: Option<String>,
    /// JSON Schema for the variant's fields.
    pub input_schema: serde_json::Value,
}

