/// CSG operation — the core building block of the IR DAG.
///
/// Each variant is either a leaf primitive or a combining/transform operation
/// that references child nodes by [`NodeId`].
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, ToolSchema)]
#[serde(tag = "type")]
#[tool(category = "modeling")]
pub enum CsgOp {
    #[tool(
        category = "primitive",
        ai_hint = "Use for rectangular/box shapes. Size is width(x), depth(y), height(z)."
    )]
    /// Axis-aligned box centered at origin.
    Cube {
        /// Size along each axis.
        size: Vec3,
    },
    #[tool(
        category = "primitive",
        ai_hint = "Axis along Z. Use for round shapes, pins, holes."
    )]
    /// Cylinder along the Z axis, centered at origin.
    Cylinder {
        /// Radius of the cylinder.
        radius: f64,
        /// Height of the cylinder.
        height: f64,
        /// Number of circular segments (0 = auto).
        segments: u32,
    },
    #[tool(category = "primitive")]
    /// Sphere centered at origin.
    Sphere {
        /// Radius of the sphere.
        radius: f64,
        /// Number of circular segments (0 = auto).
        segments: u32,
    },
    #[tool(category = "primitive")]
    /// Cone along the Z axis, centered at origin.
    Cone {
        /// Bottom radius.
        radius_bottom: f64,
        /// Top radius (0 for a point).
        radius_top: f64,
        /// Height of the cone.
        height: f64,
        /// Number of circular segments (0 = auto).
        segments: u32,
    },
    #[tool(hidden)]
    /// Empty geometry (identity for union).
    Empty,
    #[tool(category = "boolean")]
    /// Boolean union of two geometries.
    Union {
        /// Left operand.
        left: NodeId,
        /// Right operand.
        right: NodeId,
    },
    #[tool(category = "boolean")]
    /// Boolean difference (left minus right).
    Difference {
        /// Left operand (base).
        left: NodeId,
        /// Right operand (subtracted).
        right: NodeId,
    },
    #[tool(category = "boolean")]
    /// Boolean intersection of two geometries.
    Intersection {
        /// Left operand.
        left: NodeId,
        /// Right operand.
        right: NodeId,
    },
    #[tool(category = "transform")]
    /// Translation by an offset vector.
    Translate {
        /// Child node to translate.
        child: NodeId,
        /// Translation offset.
        offset: Vec3,
    },
    #[tool(category = "transform")]
    /// Rotation by Euler angles in degrees (applied as X, then Y, then Z).
    Rotate {
        /// Child node to rotate.
        child: NodeId,
        /// Rotation angles in degrees.
        angles: Vec3,
    },
    #[tool(category = "transform")]
    /// Non-uniform scale.
    Scale {
        /// Child node to scale.
        child: NodeId,
        /// Scale factors per axis.
        factor: Vec3,
    },
    #[tool(
        category = "sketch_op",
        ai_hint = "Defines a closed 2D profile. Segments are Line{start,end} or Arc{start,end,center,ccw}. Usually used inline with extrude/revolve — prefer creating extrude directly with inline sketch."
    )]
    /// A 2D sketch profile on a plane.
    ///
    /// The sketch defines a closed profile in a local 2D coordinate system.
    /// Use with [`CsgOp::Extrude`] or [`CsgOp::Revolve`] to create 3D geometry.
    Sketch2D {
        /// Origin point of the sketch plane in 3D.
        origin: Vec3,
        /// Unit vector along the local X axis.
        x_dir: Vec3,
        /// Unit vector along the local Y axis.
        y_dir: Vec3,
        /// The segments forming the closed profile.
        segments: Vec<SketchSegment2D>,
    },
    #[tool(
        category = "sketch_op",
        ai_hint = "PREFERRED for custom shapes. Pass sketch as inline object with origin, x_dir, y_dir, segments. Example: {sketch: {origin:{x:0,y:0,z:0}, x_dir:{x:1,y:0,z:0}, y_dir:{x:0,y:1,z:0}, segments:[{type:'Line',start:{x:0,y:0},end:{x:20,y:0}},{type:'Line',start:{x:20,y:0},end:{x:20,y:15}},{type:'Line',start:{x:20,y:15},end:{x:0,y:15}},{type:'Line',start:{x:0,y:15},end:{x:0,y:0}}]}, direction:{x:0,y:0,z:10}}"
    )]
    /// Extrude a sketch profile along a direction vector.
    Extrude {
        /// The sketch node to extrude.
        sketch: NodeId,
        /// Extrusion direction and distance (length of vector = extrusion depth).
        direction: Vec3,
        /// Optional twist angle in radians (rotation around extrusion axis).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        twist_angle: Option<f64>,
        /// Optional scale factor at end of extrusion (1.0 = no taper).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scale_end: Option<f64>,
    },
    #[tool(category = "sketch_op")]
    /// Revolve a sketch profile around an axis.
    Revolve {
        /// The sketch node to revolve.
        sketch: NodeId,
        /// A point on the revolution axis.
        axis_origin: Vec3,
        /// Direction of the revolution axis.
        axis_dir: Vec3,
        /// Revolution angle in degrees (360 for full revolution).
        angle_deg: f64,
    },
    #[tool(category = "pattern")]
    /// Linear pattern — repeat geometry along a direction.
    LinearPattern {
        /// Child node to pattern.
        child: NodeId,
        /// Direction vector (will be normalized).
        direction: Vec3,
        /// Number of copies (including original).
        count: u32,
        /// Spacing between copies along direction.
        spacing: f64,
    },
    #[tool(category = "pattern")]
    /// Circular pattern — repeat geometry around an axis.
    CircularPattern {
        /// Child node to pattern.
        child: NodeId,
        /// A point on the rotation axis.
        axis_origin: Vec3,
        /// Direction of the rotation axis.
        axis_dir: Vec3,
        /// Number of copies (including original).
        count: u32,
        /// Total angle span in degrees.
        angle_deg: f64,
    },
    #[tool(
        category = "modifier",
        ai_hint = "Hollow out a solid. Use parent_part_id. Great for enclosures, cups, containers."
    )]
    /// Shell — hollow out a solid by offsetting faces.
    Shell {
        /// Child node to shell.
        child: NodeId,
        /// Wall thickness (inward offset).
        thickness: f64,
    },
    #[tool(
        category = "modifier",
        ai_hint = "Apply after creating geometry. Use parent_part_id to target a part. Typical radius: 1-5mm for small features, 5-20mm for large."
    )]
    /// Fillet — round edges of a solid.
    Fillet {
        /// Child node to fillet.
        child: NodeId,
        /// Fillet radius.
        radius: f64,
    },
    #[tool(
        category = "modifier",
        ai_hint = "Bevel edges. Apply after creating geometry. Use parent_part_id to target a part."
    )]
    /// Chamfer — bevel edges of a solid.
    Chamfer {
        /// Child node to chamfer.
        child: NodeId,
        /// Chamfer distance.
        distance: f64,
    },
    #[tool(category = "sketch_op")]
    /// 2D text that can be extruded into 3D geometry.
    ///
    /// Creates sketch profiles from text glyphs, which can then be
    /// extruded and used in boolean operations for embossing/engraving.
    Text2D {
        /// Origin point of the text plane in 3D.
        origin: Vec3,
        /// X direction of the text plane (text flows along this axis).
        x_dir: Vec3,
        /// Y direction of the text plane (text height along this axis).
        y_dir: Vec3,
        /// The text string to render.
        text: String,
        /// Font name (e.g., "sans-serif", "monospace", or custom registered font).
        font: String,
        /// Text height in mm.
        height: f64,
        /// Letter spacing multiplier (1.0 = normal).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        letter_spacing: Option<f64>,
        /// Line spacing multiplier for multi-line text (1.0 = normal).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        line_spacing: Option<f64>,
        /// Text alignment.
        #[serde(default)]
        alignment: TextAlignment,
    },
    #[tool(category = "sketch_op")]
    /// Sweep a profile along a path curve.
    Sweep {
        /// The sketch node to sweep.
        sketch: NodeId,
        /// The path curve to sweep along.
        path: PathCurve,
        /// Total twist in radians (default 0).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        twist_angle: Option<f64>,
        /// Scale at start (default 1.0).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scale_start: Option<f64>,
        /// Scale at end (default 1.0).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scale_end: Option<f64>,
        /// Initial profile rotation around path tangent (radians, default 0).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        orientation: Option<f64>,
        /// Segments along path (0 = auto).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        path_segments: Option<u32>,
        /// Segments per arc in profile (default 8).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        arc_segments: Option<u32>,
    },
    #[tool(category = "sketch_op")]
    /// Loft between multiple profiles.
    Loft {
        /// Array of Sketch2D node references (>= 2).
        sketches: Vec<NodeId>,
        /// Connect last profile to first (creates tube).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        closed: Option<bool>,
    },
    #[tool(hidden)]
    /// Imported pre-tessellated mesh (e.g. from drag-drop STL/GLB).
    ImportedMesh {
        /// Flat array of vertex positions (x, y, z, x, y, z, ...).
        positions: Vec<f64>,
        /// Triangle indices.
        indices: Vec<u32>,
        /// Optional vertex normals (nx, ny, nz, ...).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        normals: Option<Vec<f64>>,
        /// Source filename for display purposes.
        #[serde(default, skip_serializing_if = "Option::is_none")]
        source: Option<String>,
    },
    #[tool(hidden)]
    /// Imported geometry from a STEP file.
    #[serde(rename = "step_import")]
    StepImport {
        /// Path to the STEP file (relative or absolute).
        path: String,
    },
    #[tool(hidden)]
    /// PCB board — evaluates the board's outline + components to 3D geometry.
    /// The `board` field contains the full PCB design data (same ecad::Pcb type).
    PcbBoard { board: Box<crate::ecad::Pcb> },
    #[tool(hidden)]
    /// Embroidery pattern — a 2D stitch design.
    EmbroideryPattern {
        /// The embroidery design data.
        design: Box<EmbroideryDesign>,
    },
}

/// A node in the IR graph.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Node {
    /// Unique identifier.
    pub id: NodeId,
    /// Optional human-readable name.
    pub name: Option<String>,
    /// The operation this node represents.
    pub op: CsgOp,
}

/// PBR material definition.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MaterialDef {
    /// Material name (e.g. "aluminum", "abs_white").
    pub name: String,
    /// Base color as `[r, g, b]` in 0.0..1.0.
    pub color: [f64; 3],
    /// Metallic factor (0.0 = dielectric, 1.0 = metal).
    pub metallic: f64,
    /// Roughness factor (0.0 = mirror, 1.0 = diffuse).
    pub roughness: f64,
    /// Density in kg/m^3 (for physics simulation).
    pub density: Option<f64>,
    /// Static friction coefficient (for physics simulation).
    pub friction: Option<f64>,
}

/// An entry in the scene — a root node with an assigned material.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SceneEntry {
    /// Root node of this scene part.
    pub root: NodeId,
    /// Material key referencing a [`MaterialDef::name`].
    pub material: String,
    /// If false, the part is hidden from the viewport (default: true).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub visible: Option<bool>,
}

